Using a runner that triggers 50 builds:

Runner pipeline
// Wrapper for https://github.com/jenkinsci/pipeline-graph-view-plugin/issues/1252
// Triggers the downstream reproducer job many times so the intermittent
// "still running" cache bug has more chances to surface.
pipeline {
    agent any

    parameters {
        string(name: 'DOWNSTREAM_JOB', defaultValue: 'issue-1252', description: 'Name of the job running Jenkinsfile.issue-1252')
        string(name: 'RUN_COUNT', defaultValue: '30', description: 'How many times to trigger the downstream job')
        booleanParam(name: 'WAIT_FOR_DOWNSTREAM', defaultValue: false, description: 'If true, block on each downstream build; if false, queue them all and return')
    }

    stages {
        stage('Trigger downstream builds') {
            steps {
                script {
                    int count = params.RUN_COUNT.toInteger()
                    for (int i = 1; i <= count; i++) {
                        echo "Triggering ${params.DOWNSTREAM_JOB} run ${i}/${count}"
                        build job: params.DOWNSTREAM_JOB,
                              wait: params.WAIT_FOR_DOWNSTREAM,
                              propagate: false,
                              quietPeriod: 0
                    }
                }
            }
        }
    }
}


